    s=open(base+path).read()
    # find block of step `after`, redirect its next to first new step
    m=re.search(r'^'+after+r':\n(?:  .*\n)*?  next: (\w+)\n', s, re.M)
    nxt=m.group(1)
    names=[n for n,_ in steps]
    block=m.group(0).replace('next: '+nxt, 'next: '+names[0])
    add=''
    for i,(n,cls) in enumerate(steps):
