import { sheetKey, useCurrentSheet, useCurrentUser } from './session';
import { useOneAtATime } from '../../query/useOneAtATime';

// Choose a sheet by typing its id and loading it. Loading an id never used before starts an empty
// sheet; loading one again re-reads what the store holds for it now.
export function SheetPicker() {
  const [user] = useCurrentUser();
  const [sheet, setSheet] = useCurrentSheet();
  const [id, setId] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();
  // The current id shows once everything kept for the sheet has been read, so what is on screen
  // under it is what the store holds for that sheet. Checked after the screen's queries have
  // mounted and started, so a query not yet begun does not count as read.
  const fetching = useIsFetching({ queryKey: sheetKey(sheet) });
  const [shown, setShown] = useState('');
  useEffect(() => {
    setShown('');
    if (fetching > 0) return;
    const timer = setTimeout(() => {
      const queries = queryClient.getQueryCache().findAll({ queryKey: sheetKey(sheet) });
      if (queries.every((q) => q.state.fetchStatus === 'idle' && q.state.status !== 'pending')) setShown(sheet);
    }, 0);
    return () => clearTimeout(timer);
  }, [sheet, fetching, queryClient]);

  const load = useMutation({
    mutationFn: (sheetId: string) => postJson<{ id: string }>('/api/sheets', { id: sheetId }),
    onSuccess: async ({ id: loaded }) => {
      setSheet(loaded);
      await queryClient.invalidateQueries({ queryKey: sheetKey(loaded) });
    },
    onError: () => setError('That sheet could not be loaded.'),
  });

  if (!user) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = id.trim();
    setError('');
    if (!trimmed) {
      setError('Type a sheet id to load.');
      return;
    }
    once(() => load.mutateAsync(trimmed));
  };
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { sheetInfoKey, sheetKey, useCurrentSheet, useCurrentUser } from './session';
import type { SheetInfo } from './session';
import { useSheetToday } from './sheetToday';
import { useOneAtATime } from '../../query/useOneAtATime';

// The sheet's own "today": shown, and changed by typing a date and saving. A blank date resets it
// to the real date.
export function SheetToday() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const today = useSheetToday();
  const [date, setDate] = useState('');
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (value: string) =>
      putJson<SheetInfo>(`/api/sheets/${encodeURIComponent(sheet)}/today?user=${encodeURIComponent(user)}`, { today: value }),
    onSuccess: async (saved) => {
      queryClient.setQueryData(sheetInfoKey(saved.id), saved);
      // Everything that depends on the date is kept under the sheet's key.
      await queryClient.invalidateQueries({ queryKey: sheetKey(saved.id) });
    },
    onError: () => setError('That date could not be set as today.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const trimmed = date.trim();
    setError('');
    if (trimmed && !/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    once(() => save.mutateAsync(trimmed));
  };

  return (
    <form onSubmit={submit}>
      <span>
        Today: <strong data-testid="sheet-today">{today}</strong>{' '}
      </span>
      <input
        data-testid="sheet-today-input"
        placeholder="yyyy-mm-dd"
        value={date}
        onChange={(e) => {
          setDate(e.target.value);
          setError('');
        }}
      />
      <button type="submit" data-testid="sheet-today-save" disabled={save.isPending}>
        Set today

